import axios from "axios";

const authAPI = axios.create({
  baseURL: process.env.REACT_APP_AUTH_API,
});

const restaurantAPI = axios.create({
  baseURL: process.env.REACT_APP_RESTAURANT_API,
});

export { authAPI, restaurantAPI };
